DROP TABLE IF EXISTS `consumers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `consumers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `installer_id` int(11) DEFAULT NULL,
  `consumer_id` varchar(30) DEFAULT NULL,
  `consumer_old_id` varchar(100) NOT NULL,
  `customer_type` enum('old','new') NOT NULL DEFAULT 'old',
  `beneficiary_id` int(11) NOT NULL,
  `name` varchar(50) NOT NULL,
  `email` varchar(50) DEFAULT NULL,
  `house_no` varchar(50) DEFAULT NULL,
  `village` varchar(50) DEFAULT NULL,
  `post` varchar(50) DEFAULT NULL,
  `block` varchar(50) DEFAULT NULL,
  `panchayat` varchar(100) DEFAULT NULL,
  `localbody_type` int(11) NOT NULL,
  `ward_no` varchar(50) DEFAULT NULL,
  `sub_district_id` int(11) DEFAULT NULL,
  `district_id` int(11) DEFAULT NULL,
  `state_id` int(11) DEFAULT NULL,
  `type` varchar(30) DEFAULT NULL,
  `phone` varchar(15) DEFAULT NULL,
  `aadhar_no` varchar(30) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `slurry_filter_unit` int(11) NOT NULL,
  `bank_loan` enum('Yes','No') DEFAULT 'No',
  `lpg_connection` enum('Yes','No') DEFAULT 'No',
  `purpose_biogas` varchar(200) DEFAULT NULL,
  `cattle_available` int(11) DEFAULT NULL,
  `number_of_cattle` text DEFAULT NULL,
  `toilet_linked` tinyint(4) DEFAULT NULL COMMENT '0 No, 1 Yes',
  `existing_biogas_plant` tinyint(4) DEFAULT NULL,
  `subsidy_availed` tinyint(4) DEFAULT NULL,
  `comment` text DEFAULT NULL,
  `date_of_reg` varchar(30) DEFAULT NULL,
  `picture` varchar(100) DEFAULT NULL,
  `is_approved` tinyint(4) DEFAULT NULL,
  `final_submission` int(11) DEFAULT NULL,
  `authorized` int(11) NOT NULL,
  `status` int(11) NOT NULL,
  `sna_remarks` text NOT NULL,
  `mnre_remarks_by_sna` text NOT NULL,
  `feedback_code` int(11) DEFAULT NULL,
  `feedback_remarks` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

