CREATE TABLE `tbl_master_ppa_bk` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) DEFAULT NULL,
  `ppa_date` date DEFAULT NULL,
  `ppa_capacity` float DEFAULT NULL,
  `ppa_electricity_per_unit_cost` float DEFAULT NULL,
  `duration_ppa` float DEFAULT NULL,
  `spv_name` varchar(255) DEFAULT NULL,
  `poc_name` varchar(50) DEFAULT NULL,
  `poc_number` varchar(12) DEFAULT NULL,
  `schedule_commissiong_date` date DEFAULT NULL,
  `revised_schedule_commissiong_date` date DEFAULT NULL,
  `state` text DEFAULT NULL,
  `district_id` text DEFAULT NULL,
  `sub_district_id` text DEFAULT NULL,
  `village_id` text DEFAULT NULL,
  `lat` varchar(20) DEFAULT NULL,
  `lng` varchar(20) DEFAULT NULL,
  `lat_long` text DEFAULT NULL,
  `location_file` text DEFAULT NULL,
  `project_location_date` date DEFAULT NULL,
  `financial_closure` varchar(3) DEFAULT NULL,
  `financial_closure_date` date DEFAULT NULL,
  `commissioned_details` text DEFAULT NULL,
  `commissioned_status` int(11) DEFAULT NULL,
  `verification_status` int(11) DEFAULT NULL,
  `checker_remarks` text DEFAULT NULL,
  `verfication_date` date DEFAULT NULL,
  `imp_verification_status` int(11) DEFAULT NULL,
  `imp_checker_remarks` text DEFAULT NULL,
  `imp_verification_date` date DEFAULT NULL,
  `com_verification_status` int(11) DEFAULT NULL,
  `com_checker_remarks` text DEFAULT NULL,
  `com_verification_date` date DEFAULT NULL,
  `sent_back_for_editing` int(11) DEFAULT NULL,
  `imp_sent_back_for_editing` int(11) DEFAULT 0,
  `com_sent_back_for_editing` int(11) DEFAULT 0,
  `send_back_remarks` text DEFAULT NULL,
  `imp_sent_back_remarks` text DEFAULT NULL,
  `com_sent_back_remarks` text DEFAULT NULL,
  `entry_date` date DEFAULT NULL,
  `cancelled_capacity` varchar(8) DEFAULT '0',
  `cancel_date` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
