--
-- Table structure for table `tbl_selected_bidder_project_bk`
--

DROP TABLE IF EXISTS `tbl_selected_bidder_project_bk`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_selected_bidder_project_bk` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bidder_id` int(11) NOT NULL,
  `tender_id` int(11) NOT NULL,
  `agency_type` varchar(5) DEFAULT NULL,
  `project_title` varchar(30) DEFAULT NULL,
  `spv_name` varchar(100) DEFAULT NULL,
  `state` int(11) DEFAULT NULL,
  `district_id` int(11) DEFAULT NULL,
  `sub_district_id` int(11) DEFAULT NULL,
  `village_id` int(11) DEFAULT NULL,
  `lat` varchar(20) DEFAULT NULL,
  `lng` varchar(20) DEFAULT NULL,
  `lat_long` text DEFAULT NULL,
  `project_location_date` date DEFAULT NULL,
  `loi_loa_date` date DEFAULT NULL,
  `tariff` float DEFAULT NULL,
  `loa_capacity` varchar(10) DEFAULT NULL,
  `loa_solar_capacity` varchar(10) DEFAULT NULL,
  `loa_wind_capacity` varchar(10) DEFAULT NULL,
  `loa_storage_capacity` varchar(10) DEFAULT NULL,
  `loa_tech` varchar(15) DEFAULT NULL,
  `ppa_psa_date` date DEFAULT NULL,
  `ppa_psa_capacity` float DEFAULT NULL,
  `ppa_psa_signed_state` int(11) DEFAULT NULL,
  `discom_name` varchar(50) DEFAULT NULL,
  `electricity_per_unit_cost` float DEFAULT NULL,
  `duration_psa` float DEFAULT NULL,
  `ppa_date` date DEFAULT NULL,
  `ppa_capacity` float DEFAULT NULL,
  `ppa_electricity_per_unit_cost` float DEFAULT NULL,
  `duration_ppa` float DEFAULT NULL,
  `schedule_commissiong_date` date DEFAULT NULL,
  `revised_schedule_commissiong_date` date DEFAULT NULL,
  `under_imp_capacity` float DEFAULT NULL,
  `under_imp_date` date DEFAULT NULL,
  `status_stage_two` varchar(25) DEFAULT NULL,
  `connectivity_applied_to` varchar(5) DEFAULT NULL,
  `stu` text DEFAULT NULL,
  `connectivity_number` varchar(15) DEFAULT NULL,
  `substation_name` varchar(45) DEFAULT NULL,
  `substation_location` varchar(75) DEFAULT NULL,
  `application_date` date DEFAULT NULL,
  `grant_date` date DEFAULT NULL,
  `actual_commissiong_date` date DEFAULT NULL,
  `actual_commissioned_capacity` float DEFAULT NULL,
  `status_lta` varchar(25) DEFAULT NULL,
  `ltoa_date` date DEFAULT NULL,
  `status_transmisison_line` varchar(25) DEFAULT NULL,
  `interconnection_vol_level` varchar(100) DEFAULT NULL,
  `commissioned_details` text DEFAULT NULL,
  `commissioned_status` int(11) DEFAULT 0 COMMENT '0= com details not submitted 1= submitted',
  `sent_back_for_editing` int(11) DEFAULT 0,
  `send_back_remarks` text DEFAULT NULL,
  `entry_date` datetime DEFAULT NULL,
  `remarks` varchar(100) DEFAULT NULL,
  `project_details_verification_status` int(11) DEFAULT NULL COMMENT '0-Pending, 1-Verified, 2-Sent Back, 4-Resubmitted',
  `project_details_verification_remarks` text DEFAULT NULL,
  `under_imp_verification_status` int(11) DEFAULT NULL COMMENT '0-Pending, 1-Verified, 2-Sent Back, 4-Resubmitted',
  `under_imp_verification_remarks` text DEFAULT NULL,
  `cancelled_capacity` varchar(8) DEFAULT '0',
  `cancel_date` date DEFAULT NULL,
  `commissioned_verification_status` int(11) DEFAULT NULL COMMENT '0-Pending, 1-Verified, 2-Sent Back, 4-Resubmitted',
  `commissioned_verification_remarks` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tender_id` (`tender_id`),
  KEY `agency_id` (`bidder_id`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
