--
-- Table structure for table `tbl_selected_bidder_project_tracker`
--

DROP TABLE IF EXISTS `tbl_selected_bidder_project_tracker`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_selected_bidder_project_tracker` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tbl_selected_bidder_project_id` int(11) DEFAULT NULL,
  `bidder_id` int(11) DEFAULT NULL,
  `tender_id` int(11) DEFAULT NULL,
  `agency_type` varchar(5) DEFAULT NULL,
  `prev_project_title` varchar(30) DEFAULT NULL,
  `curr_project_title` varchar(25) DEFAULT NULL,
  `prev_spv_name` varchar(100) DEFAULT NULL,
  `curr_spv_name` varchar(100) DEFAULT NULL,
  `prev_state` int(11) DEFAULT NULL,
  `curr_state` int(11) DEFAULT NULL,
  `prev_district_id` int(11) DEFAULT NULL,
  `curr_district_id` int(11) DEFAULT NULL,
  `prev_sub_district_id` int(11) DEFAULT NULL,
  `curr_sub_district_id` int(11) DEFAULT NULL,
  `prev_village_id` int(11) DEFAULT NULL,
  `curr_village_id` int(11) DEFAULT NULL,
  `prev_lat` varchar(20) DEFAULT NULL,
  `curr_lat` varchar(20) DEFAULT NULL,
  `prev_lng` varchar(20) DEFAULT NULL,
  `curr_lng` varchar(20) DEFAULT NULL,
  `prev_lat_long` text DEFAULT NULL,
  `curr_lat_long` text DEFAULT NULL,
  `prev_project_location_date` date DEFAULT NULL,
  `curr_project_location_date` date DEFAULT NULL,
  `prev_loi_loa_date` date DEFAULT NULL,
  `curr_loi_loa_date` date DEFAULT NULL,
  `prev_tariff` float DEFAULT NULL,
  `curr_tariff` float DEFAULT NULL,
  `prev_loa_capacity` float DEFAULT NULL,
  `curr_loa_capacity` float DEFAULT NULL,
  `prev_loa_solar_capacity` varchar(10) DEFAULT NULL,
  `curr_loa_solar_capacity` varchar(10) DEFAULT NULL,
  `prev_loa_wind_capacity` varchar(10) DEFAULT NULL,
  `curr_loa_wind_capacity` varchar(10) DEFAULT NULL,
  `prev_loa_storage_capacity` varchar(10) DEFAULT NULL,
  `curr_loa_storage_capacity` varchar(10) DEFAULT NULL,
  `prev_loa_tech` varchar(15) DEFAULT NULL,
  `curr_loa_tech` varchar(15) DEFAULT NULL,
  `prev_under_imp_capacity` float DEFAULT NULL,
  `curr_under_imp_capacity` float DEFAULT NULL,
  `prev_under_imp_date` date DEFAULT NULL,
  `curr_under_imp_date` date DEFAULT NULL,
  `prev_revised_schedule_commissiong_date` date DEFAULT NULL,
  `curr_revised_schedule_commissiong_date` date DEFAULT NULL,
  `prev_status_stage_two` varchar(25) DEFAULT NULL,
  `curr_status_stage_two` varchar(25) DEFAULT NULL,
  `prev_interconnection_vol_level` varchar(100) DEFAULT NULL,
  `curr_interconnection_vol_level` varchar(100) DEFAULT NULL,
  `prev_commissioned_status` int(11) DEFAULT 0 COMMENT '0= com details not submitted 1= submitted',
  `curr_commissioned_status` int(11) DEFAULT 0 COMMENT '0= com details not submitted 1= submitted',
  `prev_sent_back_for_editing` int(11) DEFAULT 0,
  `curr_sent_back_for_editing` int(11) DEFAULT 0,
  `prev_send_back_remarks` text DEFAULT NULL,
  `curr_send_back_remarks` text DEFAULT NULL,
  `prev_entry_date` datetime DEFAULT NULL,
  `curr_entry_date` datetime DEFAULT NULL,
  `prev_remarks` varchar(100) DEFAULT NULL,
  `curr_remarks` varchar(100) DEFAULT NULL,
  `prev_project_details_verification_status` int(11) DEFAULT NULL COMMENT '0-Pending, 1-Verified, 2-Sent Back, 4-Resubmitted',
  `curr_project_details_verification_status` int(11) DEFAULT NULL COMMENT '0-Pending, 1-Verified, 2-Sent Back, 4-Resubmitted',
  `prev_project_details_verification_remarks` text DEFAULT NULL,
  `curr_project_details_verification_remarks` text DEFAULT NULL,
  `prev_under_imp_verification_status` int(11) DEFAULT NULL COMMENT '0-Pending, 1-Verified, 2-Sent Back, 4-Resubmitted',
  `curr_under_imp_verification_status` int(11) DEFAULT NULL COMMENT '0-Pending, 1-Verified, 2-Sent Back, 4-Resubmitted',
  `prev_under_imp_verification_remarks` text DEFAULT NULL,
  `curr_under_imp_verification_remarks` text DEFAULT NULL,
  `prev_commissioned_verification_status` int(11) DEFAULT NULL COMMENT '0-Pending, 1-Verified, 2-Sent Back, 4-Resubmitted',
  `curr_commissioned_verification_status` int(11) DEFAULT NULL COMMENT '0-Pending, 1-Verified, 2-Sent Back, 4-Resubmitted',
  `prev_commissioned_verification_remarks` text DEFAULT NULL,
  `curr_commissioned_verification_remarks` text DEFAULT NULL,
  `change_type` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tender_id` (`tender_id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

